menuCss:
.menu .mm{position:absolute;inset:0;display:flex;flex-direction:column;padding:20px 20px 0;gap:14px;z-index:2}
.menu .me{display:flex;align-items:center;gap:12px}
.menu .me .av{--av:52px}
.menu .me b{display:block;font-size:17px}
.menu .me small{font-size:12px;color:var(--mut)}
.menu .lgw{padding:6px 0 0;text-align:center}
.menu .card2{border-radius:var(--r-panel,16px);background:var(--panel,var(--chipbg));box-shadow:var(--panelsh,inset 0 0 0 1px var(--line));padding:16px;display:grid;gap:12px}
.menu .card2 h2{font:var(--dspw,700) 19px var(--dsp)}
.menu .slots{display:flex;gap:8px}
.menu .slots span{flex:1;height:56px;border-radius:var(--r-btn,12px);display:grid;place-items:center;font:var(--numw,700) 28px var(--num);background:var(--bg);box-shadow:inset 0 0 0 1.5px var(--line);color:var(--tx)}
.menu .slots span.f{box-shadow:inset 0 0 0 1.5px var(--acc)}
.menu .slots span.c::after{content:"";width:2px;height:28px;background:var(--acc);animation:caret 1s steps(1) infinite}
@keyframes caret{50%{opacity:0}}
.menu .bigb{height:54px;border-radius:var(--r-btn,12px);display:grid;place-items:center;font-weight:800;font-size:16px}
.menu .bigb.p{background:var(--b-call);color:var(--b-calltx);box-shadow:var(--b-callsh,none)}
.menu .bigb.s{background:var(--chipbg);box-shadow:inset 0 0 0 1px var(--line);color:var(--tx)}
.menu .or{text-align:center;font-size:11px;letter-spacing:.24em;color:var(--mut)}
.menu .crew{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:var(--r-btn,12px);background:var(--chipbg);box-shadow:inset 0 0 0 1px var(--line)}
.menu .stk{display:flex}.menu .stk .av{--av:26px;margin-left:-8px}.menu .stk .av:first-child{margin-left:0}
.menu .crew b{flex:1;font-size:14px}.menu .crew b small{display:block;font-size:11px;color:var(--mut);font-weight:500}
.menu .live{font:800 10.5px var(--num);padding:3px 8px;border-radius:99px;background:var(--acc);color:var(--acctx);letter-spacing:.06em}
.menu .rejoin{display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:var(--r-btn,12px);background:var(--chipbg);box-shadow:inset 0 0 0 1px var(--acc)}
.menu .rejoin .dot{width:8px;height:8px;border-radius:50%;background:var(--acc);box-shadow:0 0 0 4px color-mix(in srgb,var(--acc) 25%,transparent);animation:caret 1.6s ease-in-out infinite;flex:none}
.menu .rejoin span:nth-child(2){flex:1;display:grid;gap:2px}.menu .rejoin b{font-size:12.5px}.menu .rejoin small{font-size:11px;color:var(--mut)}
.menu .rejoin .rj{font-weight:800;font-size:13px;color:var(--acc)}
.menu .nav{margin-top:auto;display:flex;justify-content:space-around;padding:10px 0 20px;box-shadow:inset 0 1px 0 var(--line);font-size:11px;color:var(--mut)}
.menu .nav span{display:grid;justify-items:center;gap:3px}.menu .nav i{font-style:normal;font-size:17px}.menu .nav .on{color:var(--acc)}

pickerCss:
.pk-m{margin:0;display:grid;gap:6px;justify-items:center}.pk-m figcaption{font:600 11.5px var(--ui);color:var(--mut)}
.pk-f{position:relative;overflow:hidden;border-radius:10px;box-shadow:0 0 0 1px var(--line),0 10px 24px rgba(0,0,0,.35)}.pk-in{position:absolute;left:0;top:0;transform-origin:0 0}
.pk-ph{display:flex;flex-direction:column;gap:12px;padding:18px 16px 0}
.pk-hd{display:flex;align-items:center;gap:10px}.pk-hd b{font:var(--dspw,700) 22px var(--dsp)}
.pk-themes{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}
.pk-themes span{display:grid;justify-items:center;gap:5px;padding:8px 4px 7px;border-radius:calc(var(--r-panel,14px) * .7);font:700 11px var(--ui);box-shadow:inset 0 0 0 1px rgba(255,255,255,.12)}
.pk-themes span.on{box-shadow:inset 0 0 0 2px var(--acc),0 0 0 3px var(--bg),0 0 0 4px var(--acc)}.pk-themes i{width:38px;height:20px;border-radius:10px}
.pk-seg{display:flex;gap:3px;padding:3px;border-radius:var(--r-btn,12px);background:var(--chipbg);box-shadow:inset 0 0 0 1px var(--line)}
.pk-seg span{flex:1;text-align:center;padding:8px 2px;border-radius:calc(var(--r-btn,12px) * .8);font:700 12px var(--ui);color:var(--mut)}.pk-seg span.on{background:var(--acc);color:var(--acctx)}
.pk-lbl{font:700 10.5px var(--ui);letter-spacing:.2em;text-transform:uppercase;color:var(--mut)}
.pk-strip{display:flex;gap:14px;align-items:center;overflow:hidden;margin-right:-16px;padding:4px 0}
.pk-dots{display:flex;gap:6px;justify-content:center}.pk-dots i{width:6px;height:6px;border-radius:50%;background:var(--line)}.pk-dots i.on{background:var(--acc);width:16px;border-radius:3px}
.pk-use{height:52px;border-radius:var(--r-btn,12px);display:grid;place-items:center;font:800 15.5px var(--ui);background:var(--b-call);color:var(--b-calltx);box-shadow:var(--b-callsh,none)}
.pk-note{font-size:11.5px;color:var(--mut);text-align:center;line-height:1.4}
.pk-lap{position:relative}
.pk-dim{position:absolute;inset:0;background:rgba(0,0,0,.55);backdrop-filter:blur(4px)}
.pk-dlg{position:absolute;left:70px;top:50px;right:70px;bottom:50px;display:grid;grid-template-columns:250px 1fr;gap:26px;padding:26px;background:var(--panel,var(--bg));box-shadow:var(--panelsh),0 30px 80px rgba(0,0,0,.6);border-radius:var(--r-panel,18px)}
.pk-dlg{background:var(--bg)}
.pk-list{display:grid;gap:6px;align-content:start}.pk-list b{font:var(--dspw,700) 24px var(--dsp);margin-bottom:8px}
.pk-list span{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:calc(var(--r-btn,12px) * .8);font:700 13.5px var(--ui);box-shadow:inset 0 0 0 1px var(--line)}
.pk-list span.on{box-shadow:inset 0 0 0 2px var(--acc)}.pk-list i{width:30px;height:16px;border-radius:8px;flex:none}
.pk-grid{display:grid;gap:14px;align-content:start}.pk-top{display:flex;align-items:center;gap:14px}.pk-top .pk-seg{width:360px}
.pk-row{display:flex;gap:22px;align-items:flex-end;justify-content:center}

loading.css:
.vx-rf{transform-box:fill-box;transform-origin:50% 100%;animation:vxrf 1.1s ease-in-out infinite}.vx-rf.b{animation-delay:-.35s}.vx-rf.c{animation-delay:-.7s}
@keyframes vxrf{0%,100%{transform:rotate(-24deg) translateX(-6px)}50%{transform:rotate(24deg) translateX(6px)}}
.vx-fly{transform-box:fill-box;animation:vxfly 1.3s cubic-bezier(.5,0,.5,1) infinite}@keyframes vxfly{0%,20%{transform:translate(0,0) rotate(0);opacity:1}100%{transform:translate(40px,-30px) rotate(200deg);opacity:0}}
.vx-trail{animation:vxtr 1.3s linear infinite}@keyframes vxtr{0%,25%{opacity:0}40%{opacity:.8}100%{opacity:0}}
.vx-pop{transform-box:fill-box;transform-origin:center;animation:vxpop 2.4s cubic-bezier(.2,1.5,.3,1) infinite}@keyframes vxpop{0%,10%{transform:scale(.5);opacity:0}24%,80%{transform:none;opacity:1}100%{opacity:0}}
.vx-sp{transform-box:fill-box;transform-origin:center;animation:vxsp 1.2s ease-in-out infinite}.vx-sp.b{animation-delay:-.6s}@keyframes vxsp{0%,100%{transform:scale(0) rotate(0)}50%{transform:scale(1) rotate(90deg)}}
.vx-gl{animation:vxgl .9s steps(3) infinite}@keyframes vxgl{0%{transform:translate(0,0)}33%{transform:translate(-6px,30px)}66%{transform:translate(4px,-40px)}}
.vx-coin{transform-box:fill-box;transform-origin:center;animation:vxcoin 1.4s cubic-bezier(.3,0,.6,1) infinite}@keyframes vxcoin{0%{transform:translateY(0) scaleX(1)}25%{transform:translateY(-34px) scaleX(.1)}50%{transform:translateY(-46px) scaleX(1)}75%{transform:translateY(-34px) scaleX(.1)}100%{transform:translateY(0) scaleX(1)}}

